head.script:
	scwin.onpageload = function() {
		inputCalendar1.setValue("12312025")
	};


scwin.checkVal = function() {
	return WebSquare.wUnit.getDomById('inputCalendar1_input').value == '12-31-2025';
}

scwin.unitTest = function() {
	//Unit
	WebSquare.wUnit.start();
	WebSquare.wUnit.addCommand("pause", "500");
	WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_input').click()");
	WebSquare.wUnit.addCommand("pause", "500");			
	//WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('inputCalendar1_input').focus()");
	//WebSquare.wUnit.addCommand("pause", "500");			

	WebSquare.wUnit.addCommand("assert", "scwin.checkVal()","true");
	WebSquare.wUnit.addCommand("pause", "500");	

	//Run test and stop
	WebSquare.wUnit.run();
	WebSquare.wUnit.stop();
}	
scwin.unitTest()
